class Solution:
    def subarraysWithKDistinct(self, nums: list[int], k: int) -> int:
        def at_most(k_distinct):
            count = collections.defaultdict(int)
            l, total = 0, 0
            for r, x in enumerate(nums):
                count[x] += 1
                while len(count) > k_distinct:
                    count[nums[l]] -= 1
                    if count[nums[l]] == 0:
                        del count[nums[l]]
                    l += 1
                total += r - l + 1
            return total
        return at_most(k) - at_most(k - 1)
